export function reloadScripts(node) {
  let scripts = []
  const scriptElements = Array.from(node.querySelectorAll('script'))

  if (scriptElements.length === 0) return

  scriptElements.forEach(origScript => {
    const script = document.createElement('script')
    Array.from(origScript.attributes).forEach(attr => {
      script.setAttribute(attr.name, attr.value)
    })
    scripts.push(script)
    origScript.remove()
  })

  // Only execute scripts when shown
  scripts.forEach(script => {
    node.appendChild(script)
  })
  scripts = [] // Clear after execution
}

